package fixture

import "testing"

func TestMax(t *testing.T) {
	if got := Max([]int{-3, -1, -2}); got != -1 {
		t.Fatalf("Max(all negative) = %d, want -1", got)
	}
	if got := Max([]int{1, 5, 2}); got != 5 {
		t.Fatalf("Max = %d, want 5", got)
	}
}
